178	export interface MCPContent {
179	  content: Array<{ type: string; text: string }>;
180	}
181	
182	export interface ExecutionContext {
183	  apiKey?: string;
184	  clientIp?: string;
185	  userAgent?: string;
186	  /**
187	   * TRUSTED authenticated tenant, resolved by the HTTP handler from a validated
188	   * inference credential (provisioned tenant key → org-<id>/user-<id>, spoof-
189	   * proof). Additive + optional: existing call sites compile unchanged and leave
190	   * it undefined. It is the ONLY input that can raise the canonical verdict
191	   * receipt's tenant binding to `authenticated_tenant`.
192	   */
193	  authenticatedTenant?: { tenantId: string; source: string };
194	}
195	
196	// Tool arguments arrive as parsed JSON from JSON-RPC — untyped at the boundary.
197	// Each handler validates its own inputs. This is the explicit trust boundary.
198	type ToolArgs = Record<string, unknown>;
199	type ToolHandler = (args: ToolArgs, ctx: ExecutionContext) => Promise<MCPContent>;
200	
201	// ============================================================================
202	// HELPER: Wrap result in MCP content format
203	// ============================================================================
204	
205	function mcpText(data: unknown): MCPContent {
206	  return { content: [{ type: 'text', text: JSON.stringify(data) }] };
207	}
208	
209	/** Safe wrapper — catches errors and returns them as standardized MCP content */
210	async function safeTool(fn: () => Promise<MCPContent>, toolName?: string): Promise<MCPContent> {
211	  try {
212	    return await fn();
213	  } catch (error: unknown) {
214	    const message = error instanceof Error ? error.message : String(error);
215	    const errorCode = classifyError(error);
216	    generalLog.error(`[ToolExecutor] ${toolName || 'unknown'} error (${errorCode}):`, error);
217	    return mcpText(mcpError(message || 'Tool execution failed', errorCode, toolName));
218	  }
219	}
