225	const governanceTools: Record<string, ToolHandler> = {
226	  reviewContent: async (args) => {
227	    const server = getGravitoMCPServer();
228	    // Normalize common parameter mismatches from MCP clients
229	    const normalized = { ...args } as Record<string, unknown>;
230	    // surface → surface_type
231	    if (normalized.surface && !normalized.surface_type) {
232	      normalized.surface_type = normalized.surface;
233	      delete normalized.surface;
234	    }
235	    // Default surface_type to 'marketing' if missing
236	    if (!normalized.surface_type) normalized.surface_type = 'marketing';
237	    // Default artifact_type to 'web_copy' if missing (valid: email|message|web_copy|doc|ad_copy)
238	    if (!normalized.artifact_type) normalized.artifact_type = 'web_copy';
239	    // Default to 'quick' mode for MCP calls — fast deterministic checks only.
240	    // Users can explicitly pass mode: 'release_gate' for full analysis.
241	    if (!normalized.mode) normalized.mode = 'quick';
242	    const result = await server.reviewContent(normalized as any);
243	    // Generate an approval_token when content passes review (not blocked)
244	    // This token can be passed to downstream tools to unlock gated operations
245	    if (result && typeof result === 'object' && !result.block_release) {
246	      try {
247	        const { getFailClosedGate } = await import('./fail-closed-gate');
248	        const gate = getFailClosedGate();
249	        const token = gate.createApprovalToken(
250	          (normalized.surface_type as string) || 'general',
251	          'reviewContent',
252	          true,
253	          [],
254	          (normalized.policy_preset as string) || 'default',
255	          false
256	        );
257	        (result as Record<string, unknown>).approval_token = token.tokenId;
258	      } catch (tokenErr) {
259	        // Non-fatal: proceed without token
260	      }
261	    }
262	    return mcpText(result);
263	  },
