342	  checkStructuralIntegrity: async (args) => {
343	    const skipClaude = args?.quick === true || args?.skipClaude === true;
344	    const verbose = args?.verbose !== false;
345	    const surfaceFilter = args?.surface as string | undefined;
346	
347	    if (skipClaude) {
348	      // Fast deterministic scan — uses validateStructuralIntegritySync
349	      const syncResult = validateStructuralIntegritySync();
350	      const filteredIssues = surfaceFilter
351	        ? syncResult.issues.filter(i => i.surface === surfaceFilter)
352	        : syncResult.issues;
353	
354	      return mcpText({
355	        score: syncResult.score,
356	        totalIssues: syncResult.totalIssues,
357	        surfaceBreakdown: syncResult.surfaceBreakdown,
358	        breakdown: syncResult.breakdown,
359	        issues: filteredIssues,
360	        validatedAt: new Date().toISOString(),
361	        adapters: '8 surfaces: website, mcp_registry, api, documentation, messaging, source_code, infrastructure, project_docs',
362	      });
363	    }
364	
365	    // Full Claude-powered analysis
366	    const result = await validateStructuralIntegrity({ skipClaude: false, verbose });
367	    const resultRecord = result as unknown as Record<string, unknown>;
368	    const allIssues = (resultRecord.issues as Array<{ surface?: string }>) || (result as StructuralIntegrityResult).allIssues || [];
369	    const filteredIssues = surfaceFilter
370	      ? allIssues.filter((i) => i.surface === surfaceFilter)
371	      : allIssues;
372	
373	    return mcpText({
374	      score: result.overallScore ?? (resultRecord.score as number),
375	      totalIssues: result.totalIssues,
376	      surfaceScores: (result as StructuralIntegrityResult).surfaceScores || {},
377	      surfaceBreakdown: (resultRecord.surfaceBreakdown as unknown as Record<string, unknown>) || {},
378	      breakdown: (resultRecord.breakdown as unknown as Record<string, unknown>) || {},
379	      claudeAnalysis: (result as StructuralIntegrityResult).claudeAnalysis,
380	      issues: filteredIssues,
381	      validatedAt: (result as StructuralIntegrityResult).validatedAt || new Date().toISOString(),
382	      adapters: '8 surfaces: website, mcp_registry, api, documentation, messaging, source_code, infrastructure, project_docs',
383	    });
