433	  updateStructuralThreshold: async (args) => {
434	    const { updateThreshold } = await import('../governance/structural-integrity-thresholds');
435	    const surfaceId = args?.surfaceId as string;
436	    if (!surfaceId) return mcpText({ error: 'surfaceId is required' });
437	    const updates: Record<string, unknown> = {};
438	    if (args?.targetScore !== undefined) updates.targetScore = args.targetScore;
439	    if (args?.severity !== undefined) updates.severity = args.severity;
440	    if (args?.enabled !== undefined) updates.enabled = args.enabled;
441	    if (args?.maxIssues !== undefined) updates.maxIssues = args.maxIssues;
442	    const result = updateThreshold(surfaceId, unsafeCast(updates, "boundary cast"));
443	    if (!result) return mcpText({ error: `Surface '${surfaceId}' not found` });
444	    return mcpText({ success: true, threshold: result });
445	  },
