// TYPES
// ============================================================================

/**
 * Surfaces that REQUIRE Gravito governance (fail-closed)
 */
export type RegulatedSurface = 
  | 'medical'
  | 'financial'
  | 'legal'
  | 'hr'
  | 'compliance';

/**
 * Surfaces that SHOULD have Gravito governance (fail-open with warning)
 */
export type AdvisorySurface =
  | 'sales'
  | 'support'
  | 'marketing';

/**
 * All surface types
 */
export type Surface = RegulatedSurface | AdvisorySurface | 'general';

/**
 * Approval token that MUST be passed to action tools
 */
export interface ApprovalToken {
  tokenId: string;
  gravitoInvocationId: string;
  surface: Surface;
  action: string;
  approved: boolean;
  expiresAt: number;
  conditions: string[];
  policyPreset: string;
  auditTrail: AuditEntry[];
  blockRelease: boolean;
  riskLevel: 'low' | 'medium' | 'high' | 'critical';
}

/**
 * Audit entry for chain of custody
 */
export interface AuditEntry {
  timestamp: number;
  tool: string;
  action: string;
  result: 'success' | 'failure' | 'blocked' | 'pending' | 'skipped';
  gravitoInvocationId: string;
  details: Record<string, unknown>;
}

/**
 * Gate decision result
 */
export interface GateDecision {
  allowed: boolean;
  reason: string;
  requiresApproval: boolean;
  surface: Surface;
  riskLevel: 'low' | 'medium' | 'high' | 'critical';
  gravitoInvocationId: string;
  auditEntry: AuditEntry;
}

/**
 * Token validation result
 */
export interface TokenValidation {
  valid: boolean;
  reason?: string;
  token?: ApprovalToken;
  gravitoInvocationId: string;
}

// ============================================================================
// CONSTANTS
// ============================================================================

/**
 * Regulated surfaces that REQUIRE approval (fail-closed)
 */
export const REGULATED_SURFACES: RegulatedSurface[] = [
  'medical',
  'financial',
  'legal',
  'hr',
  'compliance',
];

/**
 * Advisory surfaces that SHOULD have approval (fail-open with warning)
 */
export const ADVISORY_SURFACES: AdvisorySurface[] = [
  'sales',
  'support',
  'marketing',
];

/**
 * Actions that ALWAYS require approval regardless of surface
 */
export const ALWAYS_REQUIRE_APPROVAL: string[] = [
  'send_email',
  'post_content',
  'submit_form',
  'make_payment',
  'delete_data',
  'share_externally',
  'publish',
  'deploy',
];

/**
 * Token expiration time (30 minutes)
 */
export const TOKEN_EXPIRATION_MS = 30 * 60 * 1000;

// ============================================================================
// FAIL-CLOSED GATE
// ============================================================================

/**
 * Fail-Closed Gate
 * 
 * Implements the core gating logic that ensures Gravito is consulted
 * for regulated actions.

