    const allPatterns: Array<{ pattern: string; severity: string; location?: string; suggestion?: string }> = [];
    for (const unit of units) {
      allPatterns.push(...detectStructuralAntiPatterns(unit));
    }
    const byType: Record<string, number> = {};
    for (const p of allPatterns) {
      byType[p.pattern] = (byType[p.pattern] || 0) + 1;
    }
    return mcpText({ total_patterns: allPatterns.length, by_type: byType, patterns: allPatterns });
  },
};

